    /// <summary>Matching bracket for a code point, or -1 when it is not a bracket.</summary>
    public static int GetPairedBracket(int codePoint)
    {
        var i = Array.BinarySearch(BracketKeys, codePoint);
        if (i < 0) return -1;
        var v = BracketValues[i];
        return v < 0 ? -v - 1 : v;
    }

    public static BracketType GetBracketType(int codePoint)
    {
        var i = Array.BinarySearch(BracketKeys, codePoint);
        if (i < 0) return BracketType.None;
        return BracketValues[i] < 0 ? BracketType.Close : BracketType.Open;
    }

